export interface ConnectorConfig {
  /** Linear API key for GraphQL queries (Bearer token). */
  linearApiKey: string;
  /** Full Discord webhook URL including webhook_id and webhook_token. */
  discordWebhookUrl: string;
  /** Linear webhook signing secret for signature verification (optional if platform handles it). */
  linearWebhookSecret?: string;
  /** Optional fetch implementation for testing. */
  fetch?: typeof fetch;
}

export interface LinearWebhookPayload {
  action: string;
  type: string;
  data: {
    id: string;
    title: string;
    state: {
      name: string;
    };
  };
}

export interface HandleResult {
  /** Discord message ID from the webhook response. */
  discordMessageId: string;
  /** Number of comments fetched and included in the digest. */
  commentCount: number;
}

interface GraphQLVariables {
  issueId: string;
  after: string | null;
}

interface GraphQLResponse {
  data: {
    issue: {
      comments: {
        nodes: Array<{ body: string }>;
        pageInfo: {
          hasNextPage: boolean;
          endCursor: string | null;
        };
      };
    };
  };
  errors?: Array<{ message: string }>;
}

interface DiscordWebhookResponse {
  id: string;
  channel_id: string;
  content: string;
}

const GRAPHQL_QUERY = `
  query GetComments($issueId: String!, $after: String) {
    issue(id: $issueId) {
      comments(first: 100, after: $after) {
        nodes { body }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
`.trim();

const MAX_DISCORD_CONTENT_LENGTH = 2000;

async function fetchAllComments(
  issueId: string,
  linearApiKey: string,
  fetchImpl: typeof fetch,
): Promise<string[]> {
  const allBodies: string[] = [];
  let after: string | null = null;
  let hasNextPage = true;

  while (hasNextPage) {
    const variables: GraphQLVariables = { issueId, after };
    const response = await fetchImpl('https://api.linear.app/graphql', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${linearApiKey}`,
      },
      body: JSON.stringify({ query: GRAPHQL_QUERY, variables }),
    });

    if (!response.ok) {
      throw new Error(`Linear GraphQL request failed: ${response.status} ${response.statusText} at https://api.linear.app/graphql`);
    }

    const json = (await response.json()) as GraphQLResponse;

    if (json.errors && json.errors.length > 0) {
      throw new Error(`Linear GraphQL errors: ${json.errors.map((e) => e.message).join(', ')}`);
    }

    const comments = json.data?.issue?.comments;
    if (!comments) {
      throw new Error('Unexpected Linear GraphQL response shape: missing comments data');
    }

    for (const node of comments.nodes) {
      if (node.body) allBodies.push(node.body);
    }

    hasNextPage = comments.pageInfo.hasNextPage;
    after = comments.pageInfo.endCursor;
  }

  return allBodies;
}

function buildDigestMessage(title: string, commentBodies: string[]): string {
  const header = `Issue: ${title}\n\nComments:`;
  const commentLines = commentBodies.map((body) => `- ${body}`).join('\n');
  let content = `${header}\n${commentLines}`;

  if (content.length > MAX_DISCORD_CONTENT_LENGTH) {
    const truncated = content.slice(0, MAX_DISCORD_CONTENT_LENGTH - 3);
    content = `${truncated}...`;
  }

  return content;
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  // Validate required fields
  if (!payload.action || payload.action !== 'update') {
    throw new Error('Invalid payload: expected action "update"');
  }
  if (!payload.type || payload.type !== 'Issue') {
    throw new Error('Invalid payload: expected type "Issue"');
  }
  if (!payload.data?.id) {
    throw new Error('Invalid payload: missing issue.id');
  }
  if (!payload.data?.title) {
    throw new Error('Invalid payload: missing issue.title');
  }
  if (!payload.data?.state?.name || payload.data.state.name !== 'Done') {
    throw new Error('Invalid payload: issue is not closed (state.name !== "Done")');
  }

  const issueId = payload.data.id;
  const title = payload.data.title;

  // Fetch all comments via cursor pagination
  const commentBodies = await fetchAllComments(issueId, config.linearApiKey, fetchImpl);

  // Build digest message
  const content = buildDigestMessage(title, commentBodies);

  // Post to Discord webhook
  const discordResponse = await fetchImpl(config.discordWebhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  });

  if (!discordResponse.ok) {
    throw new Error(`Discord webhook request failed: ${discordResponse.status} ${discordResponse.statusText} at ${config.discordWebhookUrl}`);
  }

  const discordJson = (await discordResponse.json()) as DiscordWebhookResponse;

  return {
    discordMessageId: discordJson.id,
    commentCount: commentBodies.length,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, LinearWebhookPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      linearApiKey: 'test-linear-api-key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.discordMessageId).toBe('MESSAGE_ID_PLACEHOLDER');
    expect(result.commentCount).toBe(2);
  });
});

describe('handle', () => {
  let calls: RecordedCall[];
  let fetch: typeof fetch;
  let baseConfig: ConnectorConfig;

  beforeEach(() => {
    const { fetch: f, calls: c } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      if (req.url.startsWith('https://discord.com/api/webhooks/')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    fetch = f;
    calls = c;
    baseConfig = {
      linearApiKey: 'test-linear-api-key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    };
  });

  it('happy path: fetches comments and posts digest to Discord', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: {
        id: 'ISSUE-123',
        title: 'Test Issue',
        state: { name: 'Done' },
      },
    };

    const result = await handle(payload, baseConfig);

    expect(result.discordMessageId).toBe('MESSAGE_ID_PLACEHOLDER');
    expect(result.commentCount).toBe(2);
    expect(calls.length).toBe(2);

    // First call: Linear GraphQL
    expect(calls[0].method).toBe('POST');
    expect(calls[0].url).toBe('https://api.linear.app/graphql');
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-linear-api-key');
    expect(calls[0].json).toEqual({
      query: expect.stringContaining('GetComments'),
      variables: { issueId: 'ISSUE-123', after: null },
    });

    // Second call: Discord webhook
    expect(calls[1].method).toBe('POST');
    expect(calls[1].url).toBe('https://discord.com/api/webhooks/123/abc');
    expect(calls[1].json).toEqual({
      content: 'Issue: Test Issue\n\nComments:\n- First comment\n- Second comment',
    });
  });

  it('paginates through multiple pages of comments', async () => {
    const multiPageCalls: RecordedCall[] = [];
    const { fetch: multiFetch } = fakeFetch((req) => {
      multiPageCalls.push(req);
      if (req.url === 'https://api.linear.app/graphql') {
        const body = req.json as { variables: { after: string | null } };
        if (body.variables.after === null) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [{ body: 'Comment 1' }, { body: 'Comment 2' }],
                  pageInfo: { hasNextPage: true, endCursor: 'cursor-1' },
                },
              },
            },
          });
        }
        if (body.variables.after === 'cursor-1') {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  nodes: [{ body: 'Comment 3' }],
                  pageInfo: { hasNextPage: false, endCursor: null },
                },
              },
            },
          });
        }
      }
      if (req.url.startsWith('https://discord.com/api/webhooks/')) {
        return jsonResponse(TARGET_ENDPOINTS[1].response);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-456', title: 'Multi-page Issue', state: { name: 'Done' } },
    };

    const result = await handle(payload, { ...baseConfig, fetch: multiFetch });

    expect(result.commentCount).toBe(3);
    expect(multiPageCalls.filter((c) => c.url === 'https://api.linear.app/graphql').length).toBe(2);
    expect(multiPageCalls[0].json).toEqual(
      expect.objectContaining({ variables: { issueId: 'ISSUE-456', after: null } }),
    );
    expect(multiPageCalls[1].json).toEqual(
      expect.objectContaining({ variables: { issueId: 'ISSUE-456', after: 'cursor-1' } }),
    );
  });

  it('throws on missing issue.id', async () => {
    const payload = {
      action: 'update',
      type: 'Issue',
      data: { title: 'Test', state: { name: 'Done' } },
    } as unknown as LinearWebhookPayload;

    await expect(handle(payload, baseConfig)).rejects.toThrow('missing issue.id');
  });

  it('throws on missing issue.title', async () => {
    const payload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', state: { name: 'Done' } },
    } as unknown as LinearWebhookPayload;

    await expect(handle(payload, baseConfig)).rejects.toThrow('missing issue.title');
  });

  it('throws when issue is not closed', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'In Progress' } },
    };

    await expect(handle(payload, baseConfig)).rejects.toThrow('not closed');
  });

  it('throws on non-2xx Linear GraphQL response', async () => {
    const { fetch: errorFetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'Done' } },
    };

    await expect(handle(payload, { ...baseConfig, fetch: errorFetch })).rejects.toThrow(
      'Linear GraphQL request failed: 401 Unauthorized at https://api.linear.app/graphql',
    );
  });

  it('throws on non-2xx Discord webhook response', async () => {
    const { fetch: errorFetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse(TARGET_ENDPOINTS[0].response);
      }
      return jsonResponse({ error: 'Not Found' }, 404);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'Done' } },
    };

    await expect(handle(payload, { ...baseConfig, fetch: errorFetch })).rejects.toThrow(
      'Discord webhook request failed: 404 Not Found at https://discord.com/api/webhooks/123/abc',
    );
  });

  it('truncates message to 2000 characters', async () => {
    const longComment = 'x'.repeat(2100);
    const { fetch: truncateFetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: {
            issue: {
              comments: {
                nodes: [{ body: longComment }],
                pageInfo: { hasNextPage: false, endCursor: null },
              },
            },
          },
        });
      }
      return jsonResponse(TARGET_ENDPOINTS[1].response);
    });

    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'Done' } },
    };

    const result = await handle(payload, { ...baseConfig, fetch: truncateFetch });
    expect(result.commentCount).toBe(1);

    const discordCall = calls.find((c) => c.url.startsWith('https://discord.com/api/webhooks/'));
    expect(discordCall).toBeDefined();
    const content = (discordCall!.json as { content: string }).content;
    expect(content.length).toBeLessThanOrEqual(2000);
    expect(content.endsWith('...')).toBe(true);
  });

  it('includes Linear API key as Bearer token', async () => {
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'Done' } },
    };

    await handle(payload, baseConfig);

    const linearCall = calls.find((c) => c.url === 'https://api.linear.app/graphql');
    expect(linearCall?.headers.get('authorization')).toBe('Bearer test-linear-api-key');
  });

  it('uses Discord webhook URL from config', async () => {
    const customUrl = 'https://discord.com/api/webhooks/999/secret-token';
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'ISSUE-1', title: 'Test', state: { name: 'Done' } },
    };

    await handle(payload, { ...baseConfig, discordWebhookUrl: customUrl });

    const discordCall = calls.find((c) => c.url === customUrl);
    expect(discordCall).toBeDefined();
    expect(discordCall?.method).toBe('POST');
  });
});

# Linear Issue Closed → Discord Digest

This connector listens for Linear `issue.closed` webhooks, fetches all comments on the closed issue via cursor-paginated GraphQL queries, and posts a single digest message to a Discord channel via a webhook URL.

## What it does

1. **Receives** a Linear webhook payload when an issue transitions to a closed state (`state.name === "Done"`).
2. **Validates** the payload contains the required fields (`issue.id`, `issue.title`, closed state).
3. **Fetches all comments** from Linear's GraphQL API using cursor pagination (`after` cursor) until `hasNextPage` is false.
4. **Builds a digest message** combining the issue title and all comment bodies, truncated to Discord's 2000-character limit.
5. **Posts the digest** to a Discord webhook URL (the webhook token is embedded in the URL path).
6. **Returns** the Discord message ID and the number of comments included.

## Configuration

Provide the following via environment variables or config object:

| Config Key | Environment Variable | Description |
|------------|---------------------|-------------|
| `linearApiKey` | `LINEAR_API_KEY` | Linear API key (Bearer token) for GraphQL queries. |
| `discordWebhookUrl` | `DISCORD_WEBHOOK_URL` | Full Discord webhook URL including `webhook_id` and `webhook_token` (e.g., `https://discord.com/api/webhooks/123456/abcdef`). |
| `linearWebhookSecret` | `LINEAR_WEBHOOK_SECRET` | *(Optional)* Linear webhook signing secret. Typically verified by the platform before invoking the connector. |

## Usage Example

```typescript
import { handle } from './connector';

const payload = {
  action: 'update',
  type: 'Issue',
  data: {
    id: 'ISSUE-123',
    title: 'Fix login bug',
    state: { name: 'Done' }
  }
};

const config = {
  linearApiKey: process.env.LINEAR_API_KEY!,
  discordWebhookUrl: process.env.DISCORD_WEBHOOK_URL!,
  // linearWebhookSecret: process.env.LINEAR_WEBHOOK_SECRET, // optional
};

const result = await handle(payload, config);
console.log(`Posted digest with ${result.commentCount} comments, Discord message ID: ${result.discordMessageId}`);
```

## Assumptions

- The Linear webhook payload includes `issue.id` and `issue.title` when the issue is closed (`state.name === "Done"`).
- The Discord integration uses a webhook URL (bot token in path) to post messages; no additional auth header is required.
- Linear's GraphQL API returns comments in pages of up to 100 nodes with a `pageInfo` object containing `hasNextPage` and `endCursor` for pagination.
- The final digest message concatenates all comment bodies, each prefixed with `- `, under an "Issue: <title>\n\nComments:" header.
- Discord's 2000-character limit is enforced by truncating the message and appending `...` if necessary.
- The platform (or upstream middleware) verifies the `Linear-Signature` header using `LINEAR_WEBHOOK_SECRET` before invoking this connector; the connector does not re-verify signatures.

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://linear.app/developers/webhooks
